import{_ as n,c as a,b as e,o as p}from"./app-DuOmEixQ.js";const l={};function t(i,s){return p(),a("div",null,s[0]||(s[0]=[e(`<h1 id="jstack-jvm-线程分析工具" tabindex="-1"><a class="header-anchor" href="#jstack-jvm-线程分析工具"><span>jstack - JVM 线程分析工具</span></a></h1><p>jstack 是 JDK 内置的线程转储和分析工具，用于生成 Java 应用的线程堆栈信息，是排查线程死锁、线程饥饿、CPU 占用过高等问题的必备工具。通过 jstack 可以快速定位问题线程，分析线程状态，为性能优化提供重要依据。</p><h2 id="工具概述" tabindex="-1"><a class="header-anchor" href="#工具概述"><span>工具概述</span></a></h2><p>jstack 通过向目标 JVM 进程发送信号，获取该进程中所有线程的堆栈信息。该工具在诊断并发问题时非常有效，特别是对于发现死锁、分析线程竞争和定位 CPU 热点方法等场景有着不可替代的作用。</p><p><strong>工具特点</strong>：</p><ul><li>无侵入性：不需要修改应用代码或配置</li><li>快速获取：生成线程转储的时间很短</li><li>详细信息：包含线程状态、锁信息和堆栈跟踪</li><li>兼容性好：支持所有 JDK 8 及以上版本</li></ul><p><strong>主要用途</strong>：</p><ul><li>检测线程死锁</li><li>分析线程阻塞原因</li><li>定位 CPU 占用过高的线程</li><li>排查线程饥饿问题</li><li>分析线程竞争热点</li></ul><h2 id="安装与基本使用" tabindex="-1"><a class="header-anchor" href="#安装与基本使用"><span>安装与基本使用</span></a></h2><h3 id="环境要求" tabindex="-1"><a class="header-anchor" href="#环境要求"><span>环境要求</span></a></h3><p>jstack 随 JDK 提供，确保环境变量中配置了 <code>JAVA_HOME</code>，使其 <code>bin</code> 目录下的 jstack 可执行文件可在命令行中直接调用。</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 验证 jstack 是否可用</span></span>
<span class="line">jstack -?</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 查看 jstack 版本</span></span>
<span class="line"><span class="token function">java</span> <span class="token parameter variable">-version</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="基本语法" tabindex="-1"><a class="header-anchor" href="#基本语法"><span>基本语法</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">jstack <span class="token punctuation">[</span>options<span class="token punctuation">]</span> <span class="token operator">&lt;</span>pid<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>常用选项</strong>：</p><table><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td><code>-F</code></td><td>强制生成线程转储（当正常方式失败时）</td></tr><tr><td><code>-m</code></td><td>混合模式，同时输出 Java 和本地方法的堆栈</td></tr><tr><td><code>-l</code></td><td>长列表模式，显示锁的详细信息</td></tr><tr><td><code>-h</code></td><td>显示帮助信息</td></tr></tbody></table><h3 id="快速入门示例" tabindex="-1"><a class="header-anchor" href="#快速入门示例"><span>快速入门示例</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 查看进程 ID</span></span>
<span class="line">jps <span class="token parameter variable">-l</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 生成线程转储</span></span>
<span class="line">jstack <span class="token number">12345</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 强制生成转储（当正常方式无响应时）</span></span>
<span class="line">jstack <span class="token parameter variable">-F</span> <span class="token number">12345</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 混合模式（包含本地方法）</span></span>
<span class="line">jstack <span class="token parameter variable">-m</span> <span class="token number">12345</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 长列表模式（包含锁信息）</span></span>
<span class="line">jstack <span class="token parameter variable">-l</span> <span class="token number">12345</span> <span class="token operator">&gt;</span> thread-dump.log</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 组合使用</span></span>
<span class="line">jstack <span class="token parameter variable">-lm</span> <span class="token number">12345</span> <span class="token operator">&gt;</span> thread-dump-detailed.log</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="线程状态分析" tabindex="-1"><a class="header-anchor" href="#线程状态分析"><span>线程状态分析</span></a></h2><h3 id="理解线程状态" tabindex="-1"><a class="header-anchor" href="#理解线程状态"><span>理解线程状态</span></a></h3><p>在分析线程转储之前，需要了解 Java 线程的几种状态：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">线程状态流转图：</span>
<span class="line"></span>
<span class="line">NEW (新建)</span>
<span class="line">    ↓</span>
<span class="line">RUNNABLE (可运行)</span>
<span class="line">    │</span>
<span class="line">    ├─→ 等待锁 → BLOCKED (阻塞)</span>
<span class="line">    │</span>
<span class="line">    ├─→ 等待条件 → WAITING (等待)</span>
<span class="line">    │</span>
<span class="line">    ├─→ 超时等待 → TIMED_WAITING (限时等待)</span>
<span class="line">    │</span>
<span class="line">    └─→ 运行完成 → TERMINATED (终止)</span>
<span class="line"></span>
<span class="line">BLOCKED/WAITING/TIMED_WAITING</span>
<span class="line">    ↓</span>
<span class="line">RUNNABLE (锁释放/条件满足)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>状态说明</strong>：</p><table><thead><tr><th>状态</th><th>说明</th><th>常见场景</th></tr></thead><tbody><tr><td>NEW</td><td>线程已创建但未启动</td><td>new Thread() 后未 start()</td></tr><tr><td>RUNNABLE</td><td>可运行状态</td><td>正在执行或等待 CPU 调度</td></tr><tr><td>BLOCKED</td><td>阻塞状态</td><td>等待进入 synchronized 块</td></tr><tr><td>WAITING</td><td>等待状态</td><td>wait()、join()、LockSupport.park()</td></tr><tr><td>TIMED_WAITING</td><td>限时等待</td><td>Thread.sleep()、wait(timeout)、join(timeout)</td></tr><tr><td>TERMINATED</td><td>终止状态</td><td>线程执行完毕</td></tr></tbody></table><h3 id="解读线程转储" tabindex="-1"><a class="header-anchor" href="#解读线程转储"><span>解读线程转储</span></a></h3><p><strong>线程转储示例</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">&quot;pool-1-thread-50&quot; #50 daemon prio=10 os_prio=0 tid=0x00007f8c4c010800 nid=0x7f3a waiting on condition [0x00007f8c4a7f6000]</span>
<span class="line">   java.lang.Thread.State: TIMED_WAITING (parking)</span>
<span class="line">        at java.util.concurrent.locks.LockSupport.parkNanos</span>
<span class="line">        - waiting on &lt;0x00000000c0b3d8a0&gt; (a java.util.concurrent.LinkedBlockingQueue)</span>
<span class="line">        at java.util.concurrent.ThreadPoolExecutor$Worker.run</span>
<span class="line">        at java.lang.Thread.run</span>
<span class="line">        at java.util.concurrent.ThreadPoolExecutor$Worker.run</span>
<span class="line">        at java.util.concurrent.Executors$RunnableAdapter.call</span>
<span class="line">        at java.util.concurrent.FutureTask.run</span>
<span class="line">        at java.util.concurrent.FutureTask.run</span>
<span class="line">        at java.util.concurrent.locks.LockSupport.parkNanos(&lt;unknown&gt;:1)</span>
<span class="line">   - parking to wait for  &lt;0x00000000c0b3d8a0&gt; (a java.util.concurrent.LinkedBlockingQueue)</span>
<span class="line">       locked &lt;0x00000000c0b3d8a0&gt; (a java.util.concurrent.LinkedBlockingQueue)</span>
<span class="line"></span>
<span class="line">&quot;main&quot; #1 prio=5 os_prio=0 tid=0x00007f8c4c001000 nid=0x7f3b runnable [0x00007f8c4c00a000]</span>
<span class="line">   java.lang.Thread.State: RUNNABLE</span>
<span class="line">        at java.io.FileInputStream.readBytes(Native Method)</span>
<span class="line">        at java.io.FileInputStream.read(FileInputStream.java:255)</span>
<span class="line">        at java.io.BufferedInputStream.read(BufferedInputStream.java:345)</span>
<span class="line">        at java.io.FilterInputStream.read(FilterInputStream.java:133)</span>
<span class="line">        at com.example.MyApplication.main(MyApplication.java:45)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>关键信息解读</strong>：</p><table><thead><tr><th>信息</th><th>说明</th></tr></thead><tbody><tr><td>&quot;pool-1-thread-50&quot;</td><td>线程名称</td></tr><tr><td>#50</td><td>线程编号</td></tr><tr><td>daemon</td><td>守护线程</td></tr><tr><td>prio=10</td><td>线程优先级</td></tr><tr><td>nid=0x7f3a</td><td>操作系统线程 ID (16 进制)</td></tr><tr><td>waiting on condition</td><td>等待原因</td></tr><tr><td>java.lang.Thread.State</td><td>线程状态</td></tr><tr><td>locked</td><td>持有的锁</td></tr></tbody></table><h2 id="死锁检测" tabindex="-1"><a class="header-anchor" href="#死锁检测"><span>死锁检测</span></a></h2><h3 id="死锁特征识别" tabindex="-1"><a class="header-anchor" href="#死锁特征识别"><span>死锁特征识别</span></a></h3><p>死锁是最严重的并发问题，jstack 可以自动检测并报告死锁。</p><p><strong>死锁转储示例</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">Found one Java-level deadlock:</span>
<span class="line">=============================</span>
<span class="line">&quot;Thread-1&quot;:</span>
<span class="line">  waiting to lock Monitor 0x00007f8c4c01a800 (Object 0x00000000c0a0a4c0),</span>
<span class="line">  which is held by &quot;Thread-2&quot;</span>
<span class="line">&quot;Thread-2&quot;:</span>
<span class="line">  waiting to lock Monitor 0x00007f8c4c01b800 (Object 0x00000000c0a0a4d0),</span>
<span class="line">  which is held by &quot;Thread-1&quot;</span>
<span class="line"></span>
<span class="line">Found 1 deadlock.</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>死锁信息说明</strong>：</p><table><thead><tr><th>信息</th><th>说明</th></tr></thead><tbody><tr><td>Thread-1</td><td>死锁线程名称</td></tr><tr><td>waiting to lock</td><td>等待获取的锁</td></tr><tr><td>which is held by</td><td>持有该锁的线程</td></tr></tbody></table><h3 id="死锁排查实战" tabindex="-1"><a class="header-anchor" href="#死锁排查实战"><span>死锁排查实战</span></a></h3><p><strong>场景</strong>：两个线程相互等待对方持有的锁</p><p><strong>问题代码示例</strong>：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">DeadlockDemo</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token keyword">final</span> <span class="token class-name">Object</span> lock1 <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Object</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token keyword">final</span> <span class="token class-name">Object</span> lock2 <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Object</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token keyword">void</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> args<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 线程 1：先获取 lock1，再尝试获取 lock2</span></span>
<span class="line">        <span class="token keyword">new</span> <span class="token class-name">Thread</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">synchronized</span> <span class="token punctuation">(</span>lock1<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;Thread 1: holding lock1&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token keyword">try</span> <span class="token punctuation">{</span> <span class="token class-name">Thread</span><span class="token punctuation">.</span><span class="token function">sleep</span><span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">InterruptedException</span> e<span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line">                <span class="token keyword">synchronized</span> <span class="token punctuation">(</span>lock2<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;Thread 1: acquired lock2&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token punctuation">}</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;Deadlock-Thread-1&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">start</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        </span>
<span class="line">        <span class="token comment">// 线程 2：先获取 lock2，再尝试获取 lock1</span></span>
<span class="line">        <span class="token keyword">new</span> <span class="token class-name">Thread</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">synchronized</span> <span class="token punctuation">(</span>lock2<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;Thread 2: holding lock2&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token keyword">try</span> <span class="token punctuation">{</span> <span class="token class-name">Thread</span><span class="token punctuation">.</span><span class="token function">sleep</span><span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">InterruptedException</span> e<span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line">                <span class="token keyword">synchronized</span> <span class="token punctuation">(</span>lock1<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;Thread 2: acquired lock1&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token punctuation">}</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;Deadlock-Thread-2&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">start</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>使用 jstack 检测死锁</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 编译并运行</span></span>
<span class="line">javac DeadlockDemo.java</span>
<span class="line"><span class="token function">java</span> DeadlockDemo</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 新开终端，获取进程 ID 并检测死锁</span></span>
<span class="line">jps <span class="token parameter variable">-l</span> <span class="token operator">|</span> <span class="token function">grep</span> DeadlockDemo</span>
<span class="line"><span class="token comment"># 输出: 12345 DeadlockDemo</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 生成线程转储（会自动检测死锁）</span></span>
<span class="line">jstack <span class="token number">12345</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 或者使用 -l 选项获取更详细的锁信息</span></span>
<span class="line">jstack <span class="token parameter variable">-l</span> <span class="token number">12345</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>死锁解决方案</strong>：</p><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token comment">// 方案 1：统一锁的获取顺序</span></span>
<span class="line"><span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">safeMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 始终先获取 lock1，再获取 lock2</span></span>
<span class="line">    <span class="token keyword">synchronized</span> <span class="token punctuation">(</span>lock1<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">synchronized</span> <span class="token punctuation">(</span>lock2<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 业务逻辑</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 方案 2：使用 tryLock 超时机制</span></span>
<span class="line"><span class="token keyword">public</span> <span class="token keyword">boolean</span> <span class="token function">tryLockMethod</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">try</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>lock1<span class="token punctuation">.</span><span class="token function">tryLock</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token class-name">TimeUnit</span><span class="token punctuation">.</span><span class="token constant">SECONDS</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">try</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token keyword">if</span> <span class="token punctuation">(</span>lock2<span class="token punctuation">.</span><span class="token function">tryLock</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token class-name">TimeUnit</span><span class="token punctuation">.</span><span class="token constant">SECONDS</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                    <span class="token keyword">try</span> <span class="token punctuation">{</span></span>
<span class="line">                        <span class="token comment">// 业务逻辑</span></span>
<span class="line">                        <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line">                    <span class="token punctuation">}</span> <span class="token keyword">finally</span> <span class="token punctuation">{</span></span>
<span class="line">                        lock2<span class="token punctuation">.</span><span class="token function">unlock</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                    <span class="token punctuation">}</span></span>
<span class="line">                <span class="token punctuation">}</span></span>
<span class="line">            <span class="token punctuation">}</span> <span class="token keyword">finally</span> <span class="token punctuation">{</span></span>
<span class="line">                lock1<span class="token punctuation">.</span><span class="token function">unlock</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">InterruptedException</span> e<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">Thread</span><span class="token punctuation">.</span><span class="token function">currentThread</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">interrupt</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="自动死锁检测脚本" tabindex="-1"><a class="header-anchor" href="#自动死锁检测脚本"><span>自动死锁检测脚本</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># check-deadlock.sh - 自动检测死锁脚本</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">PID</span><span class="token operator">=</span><span class="token variable">$1</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token parameter variable">-z</span> <span class="token string">&quot;<span class="token variable">$PID</span>&quot;</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;用法: <span class="token variable">$0</span> &lt;PID&gt;&quot;</span></span>
<span class="line">    <span class="token builtin class-name">exit</span> <span class="token number">1</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;=== 检测进程 <span class="token variable">$PID</span> 的死锁 ===&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 生成线程转储</span></span>
<span class="line"><span class="token assign-left variable">DUMP</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>jstack <span class="token parameter variable">-l</span> $PID<span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 检查是否包含死锁信息</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$DUMP</span>&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-q</span> <span class="token string">&quot;Found one Java-level deadlock&quot;</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;⚠️  发现死锁！&quot;</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;=== 死锁详情 ===&quot;</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$DUMP</span>&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-A</span> <span class="token number">20</span> <span class="token string">&quot;Found one Java-level deadlock&quot;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment"># 提取死锁线程信息</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;=== 死锁线程分析 ===&quot;</span></span>
<span class="line">    <span class="token assign-left variable">DEADLOCK_THREADS</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$DUMP</span>&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-E</span> <span class="token string">&quot;^<span class="token entity" title="\\&quot;">\\&quot;</span>[A-Za-z0-9-]+<span class="token entity" title="\\&quot;">\\&quot;</span>:&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-A</span> <span class="token number">5</span> <span class="token string">&quot;waiting to lock&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token string">&quot;Thread&quot;</span><span class="token variable">)</span></span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$DEADLOCK_THREADS</span>&quot;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment"># 发送告警</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;检测到死锁，请立即处理！&quot;</span></span>
<span class="line"><span class="token keyword">else</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;✅ 未发现死锁&quot;</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="线程阻塞分析" tabindex="-1"><a class="header-anchor" href="#线程阻塞分析"><span>线程阻塞分析</span></a></h2><h3 id="blocked-状态分析" tabindex="-1"><a class="header-anchor" href="#blocked-状态分析"><span>BLOCKED 状态分析</span></a></h3><p>BLOCKED 状态的线程通常在等待获取 synchronized 锁。</p><p><strong>BLOCKED 线程示例</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">&quot;pool-1-thread-2&quot; #15 prio=5 os_prio=0 tid=0x00007f8c4c015000 nid=0x7f3c waiting for monitor entry [0x00007f8c4d8f6000]</span>
<span class="line">   java.lang.Thread.State: BLOCKED (on object monitor)</span>
<span class="line">        at com.example.Service.methodB(Service.java:20)</span>
<span class="line">        - waiting to lock &lt;0x00000000c0a0a4c0&gt; (a com.example.Service)</span>
<span class="line">        at com.example.Service.methodA(Service.java:15)</span>
<span class="line">        at com.example.Main$1.run(Main.java:10)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>分析要点</strong>：</p><ol><li><strong>waiting to lock</strong>：线程正在等待的锁对象</li><li><strong>locked by</strong>：被哪个线程持有（可以从其他线程的堆栈中找到）</li><li><strong>锁竞争激烈程度</strong>：BLOCKED 线程数量</li></ol><h3 id="waiting-状态分析" tabindex="-1"><a class="header-anchor" href="#waiting-状态分析"><span>WAITING 状态分析</span></a></h3><p>WAITING 状态的线程正在等待某个条件满足。</p><p><strong>WAITING 线程示例</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">&quot;pool-1-thread-1&quot; #14 prio=5 os_prio=0 tid=0x00007f8c4c014000 nid=0x7f3b waiting on condition [0x00007f8c4d7e5000]</span>
<span class="line">   java.lang.Thread.State: WAITING (parking)</span>
<span class="line">        at java.util.concurrent.locks.LockSupport.park</span>
<span class="line">        - waiting on &lt;0x00000000c0b3d8a0&gt; (a java.util.concurrent.LinkedBlockingQueue)</span>
<span class="line">        at java.util.concurrent.ThreadPoolExecutor$Worker.run(ThreadPoolExecutor.java:2871)</span>
<span class="line">        at java.lang.Thread.run(Thread.java:833)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>常见 WAITING 原因</strong>：</p><table><thead><tr><th>等待原因</th><th>说明</th><th>解决方案</th></tr></thead><tbody><tr><td>LockSupport.park()</td><td>使用锁同步器等待</td><td>检查锁释放逻辑</td></tr><tr><td>Object.wait()</td><td>对象条件等待</td><td>检查 notify/notifyAll</td></tr><tr><td>Thread.join()</td><td>线程等待</td><td>检查线程完成状态</td></tr><tr><td>Future.get()</td><td>异步结果等待</td><td>检查任务执行情况</td></tr></tbody></table><h3 id="线程阻塞分析脚本" tabindex="-1"><a class="header-anchor" href="#线程阻塞分析脚本"><span>线程阻塞分析脚本</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># analyze-threads.sh - 分析线程阻塞情况</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">PID</span><span class="token operator">=</span><span class="token variable">$1</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token parameter variable">-z</span> <span class="token string">&quot;<span class="token variable">$PID</span>&quot;</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;用法: <span class="token variable">$0</span> &lt;PID&gt;&quot;</span></span>
<span class="line">    <span class="token builtin class-name">exit</span> <span class="token number">1</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;=== 线程状态分析 (进程: <span class="token variable">$PID</span>) ===&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 生成线程转储</span></span>
<span class="line"><span class="token assign-left variable">DUMP</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>jstack $PID<span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 统计各状态线程数量</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 线程状态统计 ---&quot;</span></span>
<span class="line"><span class="token assign-left variable">RUNNABLE</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$DUMP</span>&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;java.lang.Thread.State: RUNNABLE&quot;</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">BLOCKED</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$DUMP</span>&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;java.lang.Thread.State: BLOCKED&quot;</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">WAITING</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$DUMP</span>&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;java.lang.Thread.State: WAITING&quot;</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">TIMED_WAITING</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$DUMP</span>&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;java.lang.Thread.State: TIMED_WAITING&quot;</span><span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;RUNNABLE: <span class="token variable">$RUNNABLE</span>&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;BLOCKED: <span class="token variable">$BLOCKED</span>&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;WAITING: <span class="token variable">$WAITING</span>&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;TIMED_WAITING: <span class="token variable">$TIMED_WAITING</span>&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- BLOCKED 线程详情 ---&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$DUMP</span>&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-A</span> <span class="token number">10</span> <span class="token string">&quot;java.lang.Thread.State: BLOCKED&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 锁竞争分析 ---&quot;</span></span>
<span class="line"><span class="token comment"># 统计每个锁的等待线程数</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$DUMP</span>&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-B</span> <span class="token number">5</span> <span class="token string">&quot;waiting to lock&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token string">&quot;Thread&quot;</span> <span class="token operator">|</span> <span class="token function">cut</span> -d<span class="token string">&#39;&quot;&#39;</span> <span class="token parameter variable">-f2</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token operator">|</span> <span class="token function">uniq</span> <span class="token parameter variable">-c</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token parameter variable">-rn</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-10</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 建议 ---&quot;</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token string">&quot;<span class="token variable">$BLOCKED</span>&quot;</span> <span class="token parameter variable">-gt</span> <span class="token number">10</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;⚠️  存在大量 BLOCKED 线程，建议检查锁使用策略&quot;</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token string">&quot;<span class="token variable">$WAITING</span>&quot;</span> <span class="token parameter variable">-gt</span> <span class="token number">50</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;⚠️  存在大量 WAITING 线程，建议检查线程池配置&quot;</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="cpu-热点分析" tabindex="-1"><a class="header-anchor" href="#cpu-热点分析"><span>CPU 热点分析</span></a></h2><h3 id="定位-cpu-占用高的线程" tabindex="-1"><a class="header-anchor" href="#定位-cpu-占用高的线程"><span>定位 CPU 占用高的线程</span></a></h3><p>当服务器 CPU 使用率过高时，可以通过 jstack 结合其他工具定位热点代码。</p><p><strong>分析步骤</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># Step 1：查看系统进程 CPU 使用情况</span></span>
<span class="line"><span class="token function">top</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Step 2：查看线程 CPU 使用情况</span></span>
<span class="line"><span class="token function">top</span> <span class="token parameter variable">-H</span> <span class="token parameter variable">-p</span> <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Step 3：找到 CPU 占用最高的线程 ID（十进制）</span></span>
<span class="line"><span class="token comment"># 假设线程 ID 为 12345</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Step 4：将线程 ID 转换为 16 进制</span></span>
<span class="line"><span class="token builtin class-name">printf</span> <span class="token string">&quot;%x<span class="token entity" title="\\n">\\n</span>&quot;</span> <span class="token number">12345</span></span>
<span class="line"><span class="token comment"># 输出: 3039</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Step 5：在 jstack 输出中查找该线程</span></span>
<span class="line">jstack <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-A</span> <span class="token number">20</span> <span class="token string">&quot; nid=0x3039&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>完整示例</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># find-cpu-hotspot.sh - 定位 CPU 热点线程</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">PID</span><span class="token operator">=</span><span class="token variable">$1</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token parameter variable">-z</span> <span class="token string">&quot;<span class="token variable">$PID</span>&quot;</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;用法: <span class="token variable">$0</span> &lt;PID&gt;&quot;</span></span>
<span class="line">    <span class="token builtin class-name">exit</span> <span class="token number">1</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;=== CPU 热点分析 (进程: <span class="token variable">$PID</span>) ===&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 获取 CPU 占用最高的线程</span></span>
<span class="line"><span class="token assign-left variable">TOP_THREAD</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">top</span> <span class="token parameter variable">-H</span> <span class="token parameter variable">-p</span> $PID <span class="token parameter variable">-b</span> <span class="token parameter variable">-n</span> <span class="token number">1</span> <span class="token operator">|</span> <span class="token function">tail</span> <span class="token parameter variable">-n</span> +8 <span class="token operator">|</span> <span class="token function">sort</span> <span class="token parameter variable">-k9</span> <span class="token parameter variable">-rn</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-1</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">THREAD_PID</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> $TOP_THREAD <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $1}&#39;</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">THREAD_CPU</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> $TOP_THREAD <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $9}&#39;</span><span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;CPU 占用最高的线程 PID: <span class="token variable">$THREAD_PID</span>&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;CPU 使用率: <span class="token variable">$THREAD_CPU</span>%&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 转换为 16 进制</span></span>
<span class="line"><span class="token assign-left variable">HEX_TID</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">printf</span> <span class="token string">&quot;%x&quot;</span> $THREAD_PID<span class="token variable">)</span></span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;线程 16 进制 ID: 0x<span class="token variable">$HEX_TID</span>&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;=== 线程堆栈 ===&quot;</span></span>
<span class="line">jstack <span class="token variable">$PID</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-A</span> <span class="token number">50</span> <span class="token string">&quot;nid=0x<span class="token variable">$HEX_TID</span>&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;=== 热点方法分析 ===&quot;</span></span>
<span class="line"><span class="token comment"># 提取堆栈中的方法调用</span></span>
<span class="line">jstack <span class="token variable">$PID</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-A</span> <span class="token number">50</span> <span class="token string">&quot;nid=0x<span class="token variable">$HEX_TID</span>&quot;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-E</span> <span class="token string">&quot;at [a-zA-Z]&quot;</span> <span class="token operator">|</span> <span class="token function">sed</span> <span class="token string">&#39;s/.*at //&#39;</span> <span class="token operator">|</span> <span class="token function">awk</span> -F<span class="token string">&#39;(&#39;</span> <span class="token string">&#39;{print $1}&#39;</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token operator">|</span> <span class="token function">uniq</span> <span class="token parameter variable">-c</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token parameter variable">-rn</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-10</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="持续-cpu-监控" tabindex="-1"><a class="header-anchor" href="#持续-cpu-监控"><span>持续 CPU 监控</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># cpu-monitor.sh - 持续监控 CPU 热点</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">PID</span><span class="token operator">=</span><span class="token variable">$1</span></span>
<span class="line"><span class="token assign-left variable">INTERVAL</span><span class="token operator">=</span><span class="token variable">\${2<span class="token operator">:-</span>5}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token parameter variable">-z</span> <span class="token string">&quot;<span class="token variable">$PID</span>&quot;</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;用法: <span class="token variable">$0</span> &lt;PID&gt; [interval]&quot;</span></span>
<span class="line">    <span class="token builtin class-name">exit</span> <span class="token number">1</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;=== 持续 CPU 热点监控 ===&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;进程: <span class="token variable">$PID</span>&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;监控间隔: <span class="token variable">\${INTERVAL}</span>秒&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">while</span> <span class="token boolean">true</span><span class="token punctuation">;</span> <span class="token keyword">do</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;--- <span class="token variable"><span class="token variable">$(</span><span class="token function">date</span><span class="token variable">)</span></span> ---&quot;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment"># 获取 CPU 最高的 3 个线程</span></span>
<span class="line">    <span class="token assign-left variable">TOP_THREADS</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">top</span> <span class="token parameter variable">-H</span> <span class="token parameter variable">-p</span> $PID <span class="token parameter variable">-b</span> <span class="token parameter variable">-n</span> <span class="token number">1</span> <span class="token operator">|</span> <span class="token function">tail</span> <span class="token parameter variable">-n</span> +8 <span class="token operator">|</span> <span class="token function">sort</span> <span class="token parameter variable">-k9</span> <span class="token parameter variable">-rn</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-3</span><span class="token variable">)</span></span></span>
<span class="line">    </span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;<span class="token variable">$TOP_THREADS</span>&quot;</span> <span class="token operator">|</span> <span class="token keyword">while</span> <span class="token builtin class-name">read</span> line<span class="token punctuation">;</span> <span class="token keyword">do</span></span>
<span class="line">        <span class="token assign-left variable">TID</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> $line <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $1}&#39;</span><span class="token variable">)</span></span></span>
<span class="line">        <span class="token assign-left variable">CPU</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">echo</span> $line <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $9}&#39;</span><span class="token variable">)</span></span></span>
<span class="line">        <span class="token assign-left variable">HEX_TID</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">printf</span> <span class="token string">&quot;%x&quot;</span> $TID<span class="token variable">)</span></span></span>
<span class="line">        </span>
<span class="line">        <span class="token builtin class-name">echo</span> <span class="token string">&quot;线程 <span class="token variable">$TID</span> (0x<span class="token variable">$HEX_TID</span>): CPU <span class="token variable">\${CPU}</span>%&quot;</span></span>
<span class="line">        jstack <span class="token variable">$PID</span> <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-A</span> <span class="token number">5</span> <span class="token string">&quot;nid=0x<span class="token variable">$HEX_TID</span>&quot;</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-6</span></span>
<span class="line">        <span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line">    <span class="token keyword">done</span></span>
<span class="line">    </span>
<span class="line">    <span class="token function">sleep</span> <span class="token variable">$INTERVAL</span></span>
<span class="line"><span class="token keyword">done</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="线程dump可视化分析" tabindex="-1"><a class="header-anchor" href="#线程dump可视化分析"><span>线程Dump可视化分析</span></a></h2><h3 id="使用在线工具分析" tabindex="-1"><a class="header-anchor" href="#使用在线工具分析"><span>使用在线工具分析</span></a></h3><p>生成线程转储后，可以使用以下工具进行可视化分析：</p><table><thead><tr><th>工具</th><th>说明</th><th>链接</th></tr></thead><tbody><tr><td>FastThread</td><td>在线线程分析工具</td><td>https://fastthread.io/</td></tr><tr><td>Thread Dump Analyzer</td><td>高级分析工具</td><td>https://threaddumpmonitor.com/</td></tr><tr><td>IBM Thread Analyzer</td><td>老牌分析工具</td><td>https://www.ibm.com/</td></tr></tbody></table><h3 id="本地分析脚本" tabindex="-1"><a class="header-anchor" href="#本地分析脚本"><span>本地分析脚本</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># analyze-thread-dump.sh - 线程转储分析</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">DUMP_FILE</span><span class="token operator">=</span><span class="token variable">$1</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">[</span> <span class="token parameter variable">-z</span> <span class="token string">&quot;<span class="token variable">$DUMP_FILE</span>&quot;</span> <span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;用法: <span class="token variable">$0</span> &lt;thread-dump-file&gt;&quot;</span></span>
<span class="line">    <span class="token builtin class-name">exit</span> <span class="token number">1</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;=== 线程转储分析报告 ===&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;分析文件: <span class="token variable">$DUMP_FILE</span>&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;分析时间: <span class="token variable"><span class="token variable">$(</span><span class="token function">date</span><span class="token variable">)</span></span>&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 基本统计</span></span>
<span class="line"><span class="token assign-left variable">TOTAL_THREADS</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">grep</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;^<span class="token entity" title="\\\\">\\\\</span><span class="token entity" title="\\&quot;">\\&quot;</span>[^<span class="token entity" title="\\\\">\\\\</span><span class="token entity" title="\\&quot;">\\&quot;</span>]*<span class="token entity" title="\\\\">\\\\</span><span class="token entity" title="\\&quot;">\\&quot;</span> #&quot;</span> $DUMP_FILE<span class="token variable">)</span></span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;总线程数: <span class="token variable">$TOTAL_THREADS</span>&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 线程状态统计</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 线程状态分布 ---&quot;</span></span>
<span class="line"><span class="token function">grep</span> <span class="token parameter variable">-o</span> <span class="token string">&quot;java.lang.Thread.State: [A-Z_]*&quot;</span> <span class="token variable">$DUMP_FILE</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token operator">|</span> <span class="token function">uniq</span> <span class="token parameter variable">-c</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token parameter variable">-rn</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 守护线程统计</span></span>
<span class="line"><span class="token assign-left variable">DAEMON_THREADS</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">grep</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;daemon&quot;</span> $DUMP_FILE<span class="token variable">)</span></span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;守护线程数: <span class="token variable">$DAEMON_THREADS</span>&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 死锁检测</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token function">grep</span> <span class="token parameter variable">-q</span> <span class="token string">&quot;Found one Java-level deadlock&quot;</span> <span class="token variable">$DUMP_FILE</span><span class="token punctuation">;</span> <span class="token keyword">then</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;⚠️  发现死锁！&quot;</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 死锁详情 ---&quot;</span></span>
<span class="line">    <span class="token function">grep</span> <span class="token parameter variable">-A</span> <span class="token number">30</span> <span class="token string">&quot;Found one Java-level deadlock&quot;</span> <span class="token variable">$DUMP_FILE</span></span>
<span class="line"><span class="token keyword">else</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line">    <span class="token builtin class-name">echo</span> <span class="token string">&quot;✅ 未发现死锁&quot;</span></span>
<span class="line"><span class="token keyword">fi</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 线程池分析</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 线程池分析 ---&quot;</span></span>
<span class="line"><span class="token function">grep</span> <span class="token parameter variable">-E</span> <span class="token string">&quot;pool-[0-9]+-thread-[0-9]+&quot;</span> <span class="token variable">$DUMP_FILE</span> <span class="token operator">|</span> <span class="token function">cut</span> -d<span class="token string">&#39;&quot;&#39;</span> <span class="token parameter variable">-f2</span> <span class="token operator">|</span> <span class="token function">sed</span> <span class="token string">&#39;s/#.*//&#39;</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token operator">|</span> <span class="token function">uniq</span> <span class="token parameter variable">-c</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token parameter variable">-rn</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-10</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 锁竞争分析</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 锁竞争分析 ---&quot;</span></span>
<span class="line"><span class="token function">grep</span> <span class="token string">&quot;waiting to lock&quot;</span> <span class="token variable">$DUMP_FILE</span> <span class="token operator">|</span> <span class="token function">awk</span> <span class="token string">&#39;{print $NF}&#39;</span> <span class="token operator">|</span> <span class="token function">sed</span> <span class="token string">&#39;s/&lt;//;s/&gt;//&#39;</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token operator">|</span> <span class="token function">uniq</span> <span class="token parameter variable">-c</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token parameter variable">-rn</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-10</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 热点方法</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;&quot;</span></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 热点方法 TOP 10 ---&quot;</span></span>
<span class="line"><span class="token function">grep</span> <span class="token string">&quot;at &quot;</span> <span class="token variable">$DUMP_FILE</span> <span class="token operator">|</span> <span class="token function">sed</span> <span class="token string">&#39;s/.*at //&#39;</span> <span class="token operator">|</span> <span class="token function">awk</span> -F<span class="token string">&#39;(&#39;</span> <span class="token string">&#39;{print $1}&#39;</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token operator">|</span> <span class="token function">uniq</span> <span class="token parameter variable">-c</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token parameter variable">-rn</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-10</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="混合模式与本地方法" tabindex="-1"><a class="header-anchor" href="#混合模式与本地方法"><span>混合模式与本地方法</span></a></h2><h3 id="使用-m-选项查看本地方法" tabindex="-1"><a class="header-anchor" href="#使用-m-选项查看本地方法"><span>使用 -m 选项查看本地方法</span></a></h3><p><code>-m</code> 选项可以同时显示 Java 方法和本地方法（如 native 方法）的堆栈。</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 混合模式输出</span></span>
<span class="line">jstack <span class="token parameter variable">-m</span> <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>输出示例</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">&quot;main&quot; #1 prio=5 os_prio=0 tid=0x00007f8c4c001000 nid=0x7f3b runnable [0x00007f8c4c00a000]</span>
<span class="line">   java.lang.Thread.State: RUNNABLE</span>
<span class="line">        at java.io.FileInputStream.readBytes(Native Method)</span>
<span class="line">        at java.io.FileInputStream.read(FileInputStream.java:255)</span>
<span class="line">        at java.io.BufferedInputStream.read(BufferedInputStream.java:345)</span>
<span class="line">        at com.example.NativeLib.read(NativeLib.java:42)</span>
<span class="line">        at com.example.Buffer.read(Buffer.java:115)</span>
<span class="line">        at com.example.Main.main(Main.java:45)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>本地方法分析要点</strong>：</p><ul><li>native 方法通常在堆栈顶部或接近顶部</li><li>可以帮助定位JNI调用问题</li><li>区分 Java 代码问题和 native 代码问题</li></ul><h3 id="分析-jni-相关问题" tabindex="-1"><a class="header-anchor" href="#分析-jni-相关问题"><span>分析 JNI 相关问题</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 查看包含 JNI 调用的线程</span></span>
<span class="line">jstack <span class="token parameter variable">-m</span> <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-E</span> <span class="token string">&quot;JNI|java.lang.Object&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 监控 JNI 内存使用</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> VM.native_memory summary <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span>/dev/null <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-A</span> <span class="token number">5</span> <span class="token string">&quot;JNI&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="远程线程转储" tabindex="-1"><a class="header-anchor" href="#远程线程转储"><span>远程线程转储</span></a></h2><h3 id="jmx-远程连接" tabindex="-1"><a class="header-anchor" href="#jmx-远程连接"><span>JMX 远程连接</span></a></h3><p>要获取远程 JVM 的线程转储，需要配置 JMX 或使用 jcmd。</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 方法 1：使用 jcmd</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> Thread.print</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 方法 2：通过 JMX 远程连接</span></span>
<span class="line"><span class="token comment"># 在远程 JVM 启动时添加 JMX 参数</span></span>
<span class="line"><span class="token function">java</span> <span class="token parameter variable">-Dcom.sun.management.jmxremote</span> <span class="token punctuation">\\</span></span>
<span class="line">     <span class="token parameter variable">-Dcom.sun.management.jmxremote.port</span><span class="token operator">=</span><span class="token number">9010</span> <span class="token punctuation">\\</span></span>
<span class="line">     <span class="token parameter variable">-Dcom.sun.management.jmxremote.ssl</span><span class="token operator">=</span>false <span class="token punctuation">\\</span></span>
<span class="line">     <span class="token parameter variable">-Dcom.sun.management.jmxremote.authenticate</span><span class="token operator">=</span>false <span class="token punctuation">\\</span></span>
<span class="line">     <span class="token parameter variable">-jar</span> app.jar</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 使用 jstack 远程连接</span></span>
<span class="line">jstack user@hostname:9010</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="ssh-隧道方式" tabindex="-1"><a class="header-anchor" href="#ssh-隧道方式"><span>SSH 隧道方式</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 创建 SSH 隧道</span></span>
<span class="line"><span class="token function">ssh</span> <span class="token parameter variable">-L</span> <span class="token number">9010</span>:localhost:9010 user@hostname</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 在本地连接</span></span>
<span class="line">jstack localhost:9010</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="最佳实践" tabindex="-1"><a class="header-anchor" href="#最佳实践"><span>最佳实践</span></a></h2><h3 id="何时使用-jstack" tabindex="-1"><a class="header-anchor" href="#何时使用-jstack"><span>何时使用 jstack</span></a></h3><p><strong>适用场景</strong>：</p><ul><li>响应变慢或无响应</li><li>CPU 使用率异常升高</li><li>怀疑存在死锁</li><li>线程数量异常增长</li><li>排查线程竞争问题</li></ul><p><strong>不适用场景</strong>：</p><ul><li>瞬时性问题（建议使用 JFR 持续录制）</li><li>需要详细性能分析（建议使用 Async Profiler）</li><li>生产环境持续监控（建议使用 JFR）</li></ul><h3 id="生成线程转储的最佳时机" tabindex="-1"><a class="header-anchor" href="#生成线程转储的最佳时机"><span>生成线程转储的最佳时机</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 问题复现时立即生成</span></span>
<span class="line">jstack <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> <span class="token operator">&gt;</span> threaddump-<span class="token variable"><span class="token variable">$(</span><span class="token function">date</span> +%Y%m%d-%H%M%S<span class="token variable">)</span></span>.log</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 多次生成以对比分析</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token for-or-select variable">i</span> <span class="token keyword">in</span> <span class="token punctuation">{</span><span class="token number">1</span><span class="token punctuation">..</span><span class="token number">5</span><span class="token punctuation">}</span><span class="token punctuation">;</span> <span class="token keyword">do</span></span>
<span class="line">    jstack <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> <span class="token operator">&gt;</span> threaddump-<span class="token variable">$i</span>.log</span>
<span class="line">    <span class="token function">sleep</span> <span class="token number">10</span></span>
<span class="line"><span class="token keyword">done</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 结合 CPU 监控生成</span></span>
<span class="line"><span class="token function">top</span> <span class="token parameter variable">-H</span> <span class="token parameter variable">-p</span> <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> <span class="token parameter variable">-b</span> <span class="token parameter variable">-n</span> <span class="token number">3</span> <span class="token operator">&gt;</span> cpu-usage.log <span class="token operator">&amp;</span></span>
<span class="line">jstack <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> <span class="token operator">&gt;</span> threaddump.log</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="性能影响" tabindex="-1"><a class="header-anchor" href="#性能影响"><span>性能影响</span></a></h3><p>jstack 是一个轻量级工具，其性能影响很小：</p><table><thead><tr><th>操作</th><th>CPU 开销</th><th>延迟影响</th><th>建议</th></tr></thead><tbody><tr><td>正常 jstack</td><td>&lt; 1%</td><td>&lt; 10ms</td><td>可频繁使用</td></tr><tr><td>jstack -F</td><td>1-2%</td><td>&lt; 50ms</td><td>问题排查时使用</td></tr><tr><td>jstack -m</td><td>1-2%</td><td>&lt; 50ms</td><td>深度分析时使用</td></tr></tbody></table><h3 id="常见问题排查" tabindex="-1"><a class="header-anchor" href="#常见问题排查"><span>常见问题排查</span></a></h3><p><strong>问题 1：jstack 无响应</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 使用 -F 强制生成</span></span>
<span class="line">jstack <span class="token parameter variable">-F</span> <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 或使用 jcmd</span></span>
<span class="line">jcmd <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> Thread.print</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>问题 2：线程状态为 &quot;Unknown&quot;</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 可能是进程正在退出</span></span>
<span class="line"><span class="token comment"># 尝试多次执行</span></span>
<span class="line">jstack <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 或等待进程稳定后重试</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>问题 3：输出不完整</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 增加超时时间</span></span>
<span class="line"><span class="token function">timeout</span> <span class="token number">30</span> jstack <span class="token parameter variable">-l</span> <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> <span class="token operator">&gt;</span> output.log</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 或分批次获取</span></span>
<span class="line">jstack <span class="token parameter variable">-l</span> <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> <span class="token operator">|</span> <span class="token function">head</span> <span class="token parameter variable">-1000</span> <span class="token operator">&gt;</span> part1.log</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="与其他工具集成" tabindex="-1"><a class="header-anchor" href="#与其他工具集成"><span>与其他工具集成</span></a></h2><h3 id="jstack-jmc" tabindex="-1"><a class="header-anchor" href="#jstack-jmc"><span>jstack + JMC</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 使用 jstack 获取初步信息</span></span>
<span class="line">jstack <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span> <span class="token operator">&gt;</span> initial-dump.log</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 结合 JMC 进行深入分析</span></span>
<span class="line">jmc <span class="token parameter variable">-open</span> <span class="token operator">&lt;</span>PID<span class="token operator">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="jstack-visualvm" tabindex="-1"><a class="header-anchor" href="#jstack-visualvm"><span>jstack + VisualVM</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token comment"># 启动 VisualVM</span></span>
<span class="line">jvisualvm</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 通过 JMX 连接远程 JVM</span></span>
<span class="line"><span class="token comment"># Thread 标签页提供可视化线程分析</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="jstack-prometheus-grafana" tabindex="-1"><a class="header-anchor" href="#jstack-prometheus-grafana"><span>jstack + Prometheus + Grafana</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># export-thread-metrics.sh - 导出线程指标到 Prometheus</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">PID</span><span class="token operator">=</span><span class="token variable">$1</span></span>
<span class="line"><span class="token assign-left variable">OUTPUT_FILE</span><span class="token operator">=</span>/tmp/thread-metrics.prom</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 生成线程转储</span></span>
<span class="line"><span class="token assign-left variable">DUMP</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>jstack $PID<span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 提取指标</span></span>
<span class="line"><span class="token assign-left variable">TOTAL_THREADS</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">grep</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;^<span class="token entity" title="\\\\">\\\\</span><span class="token entity" title="\\&quot;">\\&quot;</span>[^<span class="token entity" title="\\\\">\\\\</span><span class="token entity" title="\\&quot;">\\&quot;</span>]*<span class="token entity" title="\\\\">\\\\</span><span class="token entity" title="\\&quot;">\\&quot;</span> #&quot;</span> <span class="token operator">&lt;&lt;&lt;</span> <span class="token string">&quot;<span class="token variable">$DUMP</span>&quot;</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">RUNNABLE</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">grep</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;java.lang.Thread.State: RUNNABLE&quot;</span> <span class="token operator">&lt;&lt;&lt;</span> <span class="token string">&quot;<span class="token variable">$DUMP</span>&quot;</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">BLOCKED</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">grep</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;java.lang.Thread.State: BLOCKED&quot;</span> <span class="token operator">&lt;&lt;&lt;</span> <span class="token string">&quot;<span class="token variable">$DUMP</span>&quot;</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">WAITING</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">grep</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;java.lang.Thread.State: WAITING&quot;</span> <span class="token operator">&lt;&lt;&lt;</span> <span class="token string">&quot;<span class="token variable">$DUMP</span>&quot;</span><span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">TIMED_WAITING</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">grep</span> <span class="token parameter variable">-c</span> <span class="token string">&quot;java.lang.Thread.State: TIMED_WAITING&quot;</span> <span class="token operator">&lt;&lt;&lt;</span> <span class="token string">&quot;<span class="token variable">$DUMP</span>&quot;</span><span class="token variable">)</span></span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 输出 Prometheus 格式</span></span>
<span class="line"><span class="token function">cat</span> <span class="token operator">&gt;</span> <span class="token variable">$OUTPUT_FILE</span> <span class="token operator">&lt;&lt;</span> <span class="token string">EOF</span>
<span class="line"># HELP jvm_threads_total Total number of JVM threads</span>
<span class="line"># TYPE jvm_threads_total gauge</span>
<span class="line">jvm_threads_total <span class="token variable">$TOTAL_THREADS</span></span>
<span class="line"># HELP jvm_threads_runnable Number of runnable threads</span>
<span class="line"># TYPE jvm_threads_runnable gauge</span>
<span class="line">jvm_threads_runnable <span class="token variable">$RUNNABLE</span></span>
<span class="line"># HELP jvm_threads_blocked Number of blocked threads</span>
<span class="line"># TYPE jvm_threads_blocked gauge</span>
<span class="line">jvm_threads_blocked <span class="token variable">$BLOCKED</span></span>
<span class="line"># HELP jvm_threads_waiting Number of waiting threads</span>
<span class="line"># TYPE jvm_threads_waiting gauge</span>
<span class="line">jvm_threads_waiting <span class="token variable">$WAITING</span></span>
<span class="line"># HELP jvm_threads_timed_waiting Number of timed waiting threads</span>
<span class="line"># TYPE jvm_threads_timed_waiting gauge</span>
<span class="line">jvm_threads_timed_waiting <span class="token variable">$TIMED_WAITING</span></span>
<span class="line">EOF</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;指标已导出到 <span class="token variable">$OUTPUT_FILE</span>&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="常见问题-faq" tabindex="-1"><a class="header-anchor" href="#常见问题-faq"><span>常见问题 FAQ</span></a></h2><h3 id="q1-如何区分守护线程和用户线程" tabindex="-1"><a class="header-anchor" href="#q1-如何区分守护线程和用户线程"><span>Q1：如何区分守护线程和用户线程？</span></a></h3><p>在 jstack 输出中，守护线程会标注 <code>daemon</code> 标记：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">&quot;Service Thread&quot; #7 daemon prio=9 os_prio=0 tid=...  // 守护线程</span>
<span class="line">&quot;main&quot; #1 prio=5 os_prio=0 tid=...                   // 用户线程</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="q2-线程数多少算正常" tabindex="-1"><a class="header-anchor" href="#q2-线程数多少算正常"><span>Q2：线程数多少算正常？</span></a></h3><p>线程数量取决于应用特性：</p><table><thead><tr><th>应用类型</th><th>典型线程数</th><th>说明</th></tr></thead><tbody><tr><td>简单应用</td><td>20-50</td><td>少量业务线程</td></tr><tr><td>Web 应用</td><td>50-200</td><td>线程池处理请求</td></tr><tr><td>微服务</td><td>100-500</td><td>包含各种池</td></tr><tr><td>大数据处理</td><td>500+</td><td>并行处理大量线程</td></tr></tbody></table><h3 id="q3-为什么线程处于-runnable-但-cpu-不高" tabindex="-1"><a class="header-anchor" href="#q3-为什么线程处于-runnable-但-cpu-不高"><span>Q3：为什么线程处于 RUNNABLE 但 CPU 不高？</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">&quot;thread-1&quot; #15 prio=5 os_prio=0 tid=... nid=... runnable [...]</span>
<span class="line">   java.lang.Thread.State: RUNNABLE</span>
<span class="line">        at java.io.SocketInputStream.socketRead0(Native Method)</span>
<span class="line">        at java.io.SocketInputStream.read(SocketInputStream.java:150)</span>
<span class="line">        - locked &lt;0x00000000c0a0a4c0&gt; (a java.net.Socket)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>可能原因：</p><ul><li>I/O 阻塞操作（网络/磁盘）</li><li>等待数据库响应</li><li>外部服务调用</li><li>LockSupport.parkNanos() 短时间等待</li></ul><h3 id="q4-如何减少线程竞争" tabindex="-1"><a class="header-anchor" href="#q4-如何减少线程竞争"><span>Q4：如何减少线程竞争？</span></a></h3><div class="language-java line-numbers-mode" data-highlighter="prismjs" data-ext="java"><pre><code><span class="line"><span class="token comment">// 方案 1：减少 synchronized 范围</span></span>
<span class="line"><span class="token comment">// 不推荐</span></span>
<span class="line"><span class="token keyword">synchronized</span> <span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 大量业务逻辑</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 推荐</span></span>
<span class="line"><span class="token class-name">String</span> result<span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">synchronized</span> <span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    result <span class="token operator">=</span> cache<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>key<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 只同步必要的代码</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token comment">// 业务逻辑</span></span>
<span class="line"><span class="token function">process</span><span class="token punctuation">(</span>result<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 方案 2：使用并发工具类</span></span>
<span class="line"><span class="token comment">// 不推荐</span></span>
<span class="line"><span class="token keyword">synchronized</span> <span class="token punctuation">(</span>map<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    map<span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span>key<span class="token punctuation">,</span> value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 推荐</span></span>
<span class="line"><span class="token class-name">ConcurrentHashMap</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">,</span> <span class="token class-name">Value</span><span class="token punctuation">&gt;</span></span> map <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ConcurrentHashMap</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">map<span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span>key<span class="token punctuation">,</span> value<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 线程安全</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 方案 3：使用细粒度锁</span></span>
<span class="line"><span class="token comment">// 不推荐</span></span>
<span class="line"><span class="token keyword">synchronized</span> <span class="token punctuation">(</span>account<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    balance <span class="token operator">+=</span> amount<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 推荐：使用 Striped Lock 或并发容器</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="相关资源" tabindex="-1"><a class="header-anchor" href="#相关资源"><span>相关资源</span></a></h2><h3 id="官方文档" tabindex="-1"><a class="header-anchor" href="#官方文档"><span>官方文档</span></a></h3><ul><li><a href="https://docs.oracle.com/en/java/javase/17/docs/specs/man/jstack.html" target="_blank" rel="noopener noreferrer">jstack 官方文档</a></li><li><a href="https://docs.oracle.com/javase/8/docs/api/java/lang/Thread.html" target="_blank" rel="noopener noreferrer">Java 线程管理</a></li></ul><h3 id="性能优化参考" tabindex="-1"><a class="header-anchor" href="#性能优化参考"><span>性能优化参考</span></a></h3><ul><li><a href="https://jcip.net/" target="_blank" rel="noopener noreferrer">Java 并发编程实践</a></li><li><a href="https://www.ibm.com/docs/zh-cn/sdk-java/8?topic=diagnostics-thread-dumps" target="_blank" rel="noopener noreferrer">IBM Java 诊断指南</a></li></ul><h3 id="线程分析工具" tabindex="-1"><a class="header-anchor" href="#线程分析工具"><span>线程分析工具</span></a></h3><ul><li><a href="https://fastthread.io/" target="_blank" rel="noopener noreferrer">FastThread 在线分析</a></li><li><a href="https://threaddumpmonitor.com/" target="_blank" rel="noopener noreferrer">Thread Dump Analyzer</a></li></ul><h3 id="社区资源" tabindex="-1"><a class="header-anchor" href="#社区资源"><span>社区资源</span></a></h3><ul><li><a href="https://stackoverflow.com/questions/tagged/jstack" target="_blank" rel="noopener noreferrer">Stack Overflow - jstack</a></li><li><a href="https://github.com/topics/thread-dump" target="_blank" rel="noopener noreferrer">GitHub - 线程分析工具集</a></li></ul>`,139)]))}const o=n(l,[["render",t]]),r=JSON.parse('{"path":"/java/advanced/diagnostic-tools/diagnostic-jstack.html","title":"jstack - JVM 线程分析工具","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1767688846000,"contributors":[{"name":"zhaomy","username":"zhaomy","email":"3036190149@qq.com","commits":1,"url":"https://github.com/zhaomy"}],"changelog":[{"hash":"002042d6ccab469ab518aca6e5eb5ee2c566721e","time":1767688846000,"email":"3036190149@qq.com","author":"zhaomy","message":"docs: 新增Java诊断与监控工具相关文档"}]},"filePathRelative":"java/advanced/diagnostic-tools/diagnostic-jstack.md","excerpt":"\\n<p>jstack 是 JDK 内置的线程转储和分析工具，用于生成 Java 应用的线程堆栈信息，是排查线程死锁、线程饥饿、CPU 占用过高等问题的必备工具。通过 jstack 可以快速定位问题线程，分析线程状态，为性能优化提供重要依据。</p>\\n<h2>工具概述</h2>\\n<p>jstack 通过向目标 JVM 进程发送信号，获取该进程中所有线程的堆栈信息。该工具在诊断并发问题时非常有效，特别是对于发现死锁、分析线程竞争和定位 CPU 热点方法等场景有着不可替代的作用。</p>\\n<p><strong>工具特点</strong>：</p>\\n<ul>\\n<li>无侵入性：不需要修改应用代码或配置</li>\\n<li>快速获取：生成线程转储的时间很短</li>\\n<li>详细信息：包含线程状态、锁信息和堆栈跟踪</li>\\n<li>兼容性好：支持所有 JDK 8 及以上版本</li>\\n</ul>"}');export{o as comp,r as data};
